// tools/default_bg/NOTICE.md.
// Used by the Photo face and the screensaver whenever no user photo is set.
// The pixel data lives in default_bg_data.inc (generated by
// tools/default_bg/gen_default_bg.py) and is compiled exactly once by
// default_bg_data.cpp; everyone else links against this extern so the
// 131 KiB array isn't duplicated per translation unit.
#pragma once
#include <stdint.h>

#define DEFAULT_BG_W 240
#define DEFAULT_BG_H 280

extern const uint16_t DEFAULT_BG[DEFAULT_BG_W * DEFAULT_BG_H];
